import {openSQLiteStore} from '../../src/services/storage/sqlite.js';import {createSQLiteBotDatabase} from '../../src/services/storage/sqliteBotDatabase.js';import {addXp} from '../../src/services/leveling/xpSystem.js';
const [path,guild,user,mode]=process.argv.slice(2),sqlite=await openSQLiteStore({path,busyTimeout:5000}),adapter=createSQLiteBotDatabase(sqlite),client={homeGuildId:guild,db:{getStatus:()=>({isDegraded:false}),isAvailable:()=>true,db:adapter}},g={id:guild,name:'Test',roles:{cache:new Map()},members:{me:{}}},member={user:{id:user,tag:'Test'},roles:{cache:new Map()}};
